"""Shared, verified paper records used by the per-topic extras files. Titles are checked against the arXiv
abstract pages by tools/check_papers.py; summaries and numbers come from the papers read for each deck."""


def paper(title, authors, venue, year, url, summary, number=''):
    return dict(title=title, authors=authors, venue=venue, year=year, url=url, summary=summary, number=number)


def arxiv(i):
    return f'https://arxiv.org/abs/{i}'


