# Inference-guide records live in extras_inference.P; expose the ones other topics reuse.
def _inference_records():
    from extras_inference import P as INF
    for k in ('vllm', 'orca', 'sglang', 'pope', 'megatron', 'splitwise', 'distserve'):
        PAPERS.setdefault(k, INF[k])


_inference_records()
